import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride_d, int stride_h, int stride_w,
                                            int pad_d, int pad_h, int pad_w,
                                            int out_pad_d, int out_pad_h, int out_pad_w,
                                            int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kd, int kh, int kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw)
{
  constexpr int Threads  = 128;
  constexpr int P_SUB    = 4;
  constexpr int P_TILE   = Threads * P_SUB;
  constexpr int KCHUNK   = 128;
  constexpr int CO_TILE  = 16;
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int co_base = blockIdx.z * CO_TILE;
  const int p0 = blockIdx.x * P_TILE;
  const int P_total = Dout * Hout * Wout;
  int p[P_SUB];
  bool pvalid[P_SUB];
  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    p[r] = p0 + tid + r * Threads;
    pvalid[r] = (p[r] < P_total);
  }

  const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWci = (int64_t)Cout * kd * kh * kw;
  const int64_t sWco = (int64_t)kd * kh * kw;
  const int64_t sWkd = (int64_t)kh * kw;
  const int64_t sWkh = (int64_t)kw;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Din, Hin, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, kd, kh, kw),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );

  __shared__ T sW_raw[KCHUNK * CO_TILE];
  __shared__ int sCi[KCHUNK];
  __shared__ int sKz[KCHUNK];
  __shared__ int sKy[KCHUNK];
  __shared__ int sKx[KCHUNK];

  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<KCHUNK>{}, Int<CO_TILE>{}),
      make_stride(Int<CO_TILE>{}, Int<1>{})
  );

  int od[P_SUB], oh[P_SUB], ow[P_SUB];
  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    od[r] = 0; oh[r] = 0; ow[r] = 0;
    if (pvalid[r]) {
      od[r] = p[r] / (Hout * Wout);
      int rem = p[r] - od[r] * (Hout * Wout);
      oh[r] = rem / Wout;
      ow[r] = rem - oh[r] * Wout;
    }
  }
  float acc[P_SUB][CO_TILE];
  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    #pragma unroll
    for (int cc = 0; cc < CO_TILE; ++cc) {
      int co = co_base + cc;
      float bv = 0.0f;
      if (B != nullptr && co < Cout) bv = (float)B[co];
      acc[r][cc] = bv;
    }
  }

  const int K_total = Cin * kd * kh * kw;
  const bool unit_stride = (sd == 1 && sh == 1 && sw == 1);

  for (int k0 = 0; k0 < K_total; k0 += KCHUNK) {
    const int kc = min(KCHUNK, K_total - k0);

    for (int idx = tid; idx < KCHUNK; idx += Threads) {
      int kg = k0 + idx;
      bool kv = (kg < K_total);

      int ci = 0, kz = 0, ky = 0, kx = 0;
      if (kv) {
        kx = kg % kw;
        int r0 = kg / kw;
        ky = r0 % kh;
        int r1 = r0 / kh;
        kz = r1 % kd;
        ci = r1 / kd;
      }

      sCi[idx] = ci;
      sKz[idx] = kz;
      sKy[idx] = ky;
      sKx[idx] = kx;

      #pragma unroll
      for (int cc = 0; cc < CO_TILE; ++cc) {
        int co = co_base + cc;
        T wv = T(0);
        if (kv && co < Cout) {
          wv = mW(ci, co, kz, ky, kx);
        }
        sW(idx, cc) = wv;
      }
    }
    __syncthreads();

    #pragma unroll
    for (int r = 0; r < P_SUB; ++r) {
      if (pvalid[r]) {
        for (int idx = 0; idx < kc; ++idx) {
          const int ci = sCi[idx];
          const int kz = sKz[idx];
          const int ky = sKy[idx];
          const int kx = sKx[idx];
          int id, ih, iw;
          bool valid;
          if (unit_stride) {
            id = od[r] + pd - kz;
            ih = oh[r] + ph - ky;
            iw = ow[r] + pw - kx;
            valid = ((unsigned)id < (unsigned)Din) &&
                    ((unsigned)ih < (unsigned)Hin) &&
                    ((unsigned)iw < (unsigned)Win);
          } else {
            int nd = od[r] + pd - kz;
            int nh = oh[r] + ph - ky;
            int nw = ow[r] + pw - kx;
            valid = false;
            id = ih = iw = 0;
            if (nd >= 0 && nh >= 0 && nw >= 0 &&
                (nd % sd) == 0 && (nh % sh) == 0 && (nw % sw) == 0) {
              id = nd / sd;
              ih = nh / sh;
              iw = nw / sw;
              valid = ((unsigned)id < (unsigned)Din) &&
                      ((unsigned)ih < (unsigned)Hin) &&
                      ((unsigned)iw < (unsigned)Win);
            }
          }
          if (valid) {
            const float xv = (float)mX(ci, id, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CO_TILE; ++cc) {
              acc[r][cc] += xv * (float)sW(idx, cc);
            }
          }
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    if (pvalid[r]) {
      #pragma unroll
      for (int cc = 0; cc < CO_TILE; ++cc) {
        int co = co_base + cc;
        if (co < Cout) {
          mY(co, od[r], oh[r], ow[r]) = (T)acc[r][cc];
        }
      }
    }
  }
}

__device__ __forceinline__ int floor_div_i(int a, int b) {
  return (a >= 0) ? (a / b) : -((-a + b - 1) / b);
}
__device__ __forceinline__ int ceil_div_i(int a, int b) {
  return -floor_div_i(-a, b);
}
__device__ __forceinline__ bool tile_input_range(
    int out_base, int out_tile, int out_size,
    int k, int pad, int stride, int in_size,
    int& in_base, int& in_span) {
  int out_hi = out_base + out_tile - 1;
  if (out_hi > out_size - 1) out_hi = out_size - 1;
  if (out_hi < out_base) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  const int lo_num = out_base + pad - (k - 1);
  const int hi_num = out_hi + pad;
  if (hi_num < 0) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  const int first = ceil_div_i(lo_num, stride);
  const int last = floor_div_i(hi_num, stride);
  if (first > last) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  in_base = (first > 0) ? first : 0;
  int in_hi = (last < in_size - 1) ? last : (in_size - 1);
  in_span = in_hi - in_base + 1;
  if (in_span <= 0) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  return true;
}
template <typename T>
__global__ void conv_transpose3d_smem_tile_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kd, int kh, int kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw)
{
  // Register-blocked cooperative tile kernel. Retuned tiling to cut register
  // pressure and raise occupancy (profiler showed 157 regs/thread, 25% theoretical
  // occupancy): each thread now computes OW_REP=2 outputs along W for CO_TILE=8
  // output channels, so the per-thread accumulator array drops from 4x16=64 to
  // 2x8=16 floats. The spatial tile is smaller (OD_TILE=1), which also quadruples
  // the grid size for better load balance and latency hiding across SMs.
  constexpr int Threads = 128;
  constexpr int OD_TILE = 1;
  constexpr int OH_TILE = 4;
  constexpr int OW_SUB = 32;
  constexpr int OW_REP = 2;
  constexpr int OW_TILE = OW_REP * OW_SUB;
  constexpr int CI_TILE = 2;
  constexpr int CO_TILE = 8;
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int co_base = blockIdx.z * CO_TILE;
  const int wtiles = (Wout + OW_TILE - 1) / OW_TILE;
  const int htiles = (Hout + OH_TILE - 1) / OH_TILE;
  const int tile = blockIdx.x;
  const int wt = tile % wtiles;
  const int tile_rem = tile / wtiles;
  const int ht = tile_rem % htiles;
  const int dt = tile_rem / htiles;
  const int od_base = dt * OD_TILE;
  const int oh_base = ht * OH_TILE;
  const int ow_base = wt * OW_TILE;
  const int ow_l = tid % OW_SUB;
  const int t_rem = tid / OW_SUB;
  const int oh_l = t_rem % OH_TILE;
  const int od_l = t_rem / OH_TILE;
  const int od = od_base + od_l;
  const int oh = oh_base + oh_l;
  const bool dh_valid = (od < Dout) && (oh < Hout);
  int ow[OW_REP];
  bool ovalid[OW_REP];
  bool any_ovalid = false;
  #pragma unroll
  for (int j = 0; j < OW_REP; ++j) {
    ow[j] = ow_base + ow_l + j * OW_SUB;
    ovalid[j] = dh_valid && (ow[j] < Wout);
    any_ovalid = any_ovalid || ovalid[j];
  }
  const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sWci = (int64_t)Cout * kd * kh * kw;
  const int64_t sWco = (int64_t)kd * kh * kw;
  const int64_t sWkd = (int64_t)kh * kw;
  const int64_t sWkh = (int64_t)kw;
  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Din, Hin, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, kd, kh, kw),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );
  extern __shared__ T s_mem[];
  int id0, dspan, ih0, hspan, iw0, wspan;
  const bool has_d = tile_input_range(od_base, OD_TILE, Dout, kd, pd, sd, Din, id0, dspan);
  const bool has_h = tile_input_range(oh_base, OH_TILE, Hout, kh, ph, sh, Hin, ih0, hspan);
  const bool has_w = tile_input_range(ow_base, OW_TILE, Wout, kw, pw, sw, Win, iw0, wspan);
  const bool has_overlap = has_d && has_h && has_w;
  const int k_lin = kd * kh * kw;
  T* sX_raw = s_mem;
  T* sW_raw = s_mem + (size_t)CI_TILE * (size_t)dspan * (size_t)hspan * (size_t)wspan;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CI_TILE>{}, dspan, hspan, wspan),
      make_stride(dspan * hspan * wspan, hspan * wspan, wspan, Int<1>{})
  );
  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CI_TILE>{}, Int<CO_TILE>{}, k_lin),
      make_stride((int64_t)CO_TILE * k_lin, k_lin, Int<1>{})
  );
  float acc[OW_REP][CO_TILE];
  #pragma unroll
  for (int j = 0; j < OW_REP; ++j) {
    #pragma unroll
    for (int cc = 0; cc < CO_TILE; ++cc) {
      const int co = co_base + cc;
      float bv = 0.0f;
      if (B != nullptr && co < Cout) bv = (float)B[co];
      acc[j][cc] = bv;
    }
  }
  const bool unit_stride = (sd == 1 && sh == 1 && sw == 1);
  if (has_overlap) {
    for (int ci0 = 0; ci0 < Cin; ci0 += CI_TILE) {
      const int ci_count = min(CI_TILE, Cin - ci0);
      const int tile_elems = ci_count * dspan * hspan * wspan;
      for (int idx = tid; idx < tile_elems; idx += Threads) {
        const int iw_l = idx % wspan;
        int rem = idx / wspan;
        const int ih_l = rem % hspan;
        rem /= hspan;
        const int id_l = rem % dspan;
        const int ci_l = rem / dspan;
        sX(ci_l, id_l, ih_l, iw_l) = mX(
            ci0 + ci_l,
            id0 + id_l,
            ih0 + ih_l,
            iw0 + iw_l
        );
      }
      const int w_elems = ci_count * CO_TILE * k_lin;
      for (int idx = tid; idx < w_elems; idx += Threads) {
        const int k = idx % k_lin;
        int rem = idx / k_lin;
        const int cc = rem % CO_TILE;
        const int ci_l = rem / CO_TILE;
        const int co = co_base + cc;
        sW(ci_l, cc, k) = (co < Cout) ? mW(ci0 + ci_l, co, k / (kh * kw), (k / kw) % kh, k % kw) : T(0);
      }
      __syncthreads();
      if (any_ovalid) {
        const int hs_hw = hspan * wspan;
        for (int ci_l = 0; ci_l < ci_count; ++ci_l) {
          const int ci_base = ci_l * dspan * hs_hw;
          for (int kz = 0; kz < kd; ++kz) {
            int id_l;
            bool dvalid;
            if (unit_stride) {
              id_l = (od + pd - kz) - id0;
              dvalid = ((unsigned)id_l < (unsigned)dspan);
            } else {
              const int nd = od + pd - kz;
              dvalid = false;
              id_l = 0;
              if (nd >= 0 && (nd % sd) == 0) {
                id_l = nd / sd - id0;
                dvalid = ((unsigned)id_l < (unsigned)dspan);
              }
            }
            if (!dvalid) continue;
            const int dz_base = ci_base + id_l * hs_hw;
            for (int ky = 0; ky < kh; ++ky) {
              int ih_l;
              bool hvalid;
              if (unit_stride) {
                ih_l = (oh + ph - ky) - ih0;
                hvalid = ((unsigned)ih_l < (unsigned)hspan);
              } else {
                const int nh = oh + ph - ky;
                hvalid = false;
                ih_l = 0;
                if (nh >= 0 && (nh % sh) == 0) {
                  ih_l = nh / sh - ih0;
                  hvalid = ((unsigned)ih_l < (unsigned)hspan);
                }
              }
              if (!hvalid) continue;
              const T* __restrict__ xrow = sX_raw + dz_base + ih_l * wspan;
              const int ky_base = (kz * kh + ky) * kw;
              if (unit_stride) {
                int iw_l[OW_REP];
                #pragma unroll
                for (int j = 0; j < OW_REP; ++j) {
                  iw_l[j] = ovalid[j] ? ((ow[j] + pw) - iw0) : -1;
                }
                for (int kx = 0; kx < kw; ++kx) {
                  int l[OW_REP];
                  bool v[OW_REP];
                  bool anyv = false;
                  #pragma unroll
                  for (int j = 0; j < OW_REP; ++j) {
                    l[j] = iw_l[j] - kx;
                    v[j] = ((unsigned)l[j] < (unsigned)wspan);
                    anyv = anyv || v[j];
                  }
                  if (anyv) {
                    const T* __restrict__ wrow = sW_raw + ((size_t)ci_l * CO_TILE) * k_lin + (size_t)(ky_base + kx);
                    float wreg[CO_TILE];
                    #pragma unroll
                    for (int cc = 0; cc < CO_TILE; ++cc) {
                      wreg[cc] = (float)wrow[(size_t)cc * k_lin];
                    }
                    #pragma unroll
                    for (int j = 0; j < OW_REP; ++j) {
                      if (v[j]) {
                        const float xv = (float)xrow[l[j]];
                        #pragma unroll
                        for (int cc = 0; cc < CO_TILE; ++cc) {
                          acc[j][cc] += xv * wreg[cc];
                        }
                      }
                    }
                  }
                }
              } else {
                for (int kx = 0; kx < kw; ++kx) {
                  int l[OW_REP];
                  bool v[OW_REP];
                  bool anyv = false;
                  #pragma unroll
                  for (int j = 0; j < OW_REP; ++j) {
                    l[j] = -1;
                    v[j] = false;
                    if (ovalid[j]) {
                      const int nw = ow[j] + pw - kx;
                      if (nw >= 0 && (nw % sw) == 0) {
                        const int lj = nw / sw - iw0;
                        if ((unsigned)lj < (unsigned)wspan) {
                          l[j] = lj;
                          v[j] = true;
                        }
                      }
                    }
                    anyv = anyv || v[j];
                  }
                  if (anyv) {
                    const T* __restrict__ wrow = sW_raw + ((size_t)ci_l * CO_TILE) * k_lin + (size_t)(ky_base + kx);
                    float wreg[CO_TILE];
                    #pragma unroll
                    for (int cc = 0; cc < CO_TILE; ++cc) {
                      wreg[cc] = (float)wrow[(size_t)cc * k_lin];
                    }
                    #pragma unroll
                    for (int j = 0; j < OW_REP; ++j) {
                      if (v[j]) {
                        const float xv = (float)xrow[l[j]];
                        #pragma unroll
                        for (int cc = 0; cc < CO_TILE; ++cc) {
                          acc[j][cc] += xv * wreg[cc];
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
      __syncthreads();
    }
  }
  #pragma unroll
  for (int j = 0; j < OW_REP; ++j) {
    if (ovalid[j]) {
      #pragma unroll
      for (int cc = 0; cc < CO_TILE; ++cc) {
        const int co = co_base + cc;
        if (co < Cout) {
          mY(co, od, oh, ow[j]) = (T)acc[j][cc];
        }
      }
    }
  }
}
torch::Tensor conv_transpose3d_cute_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride_d, int stride_h, int stride_w,
                                            int pad_d, int pad_h, int pad_w,
                                            int out_pad_d, int out_pad_h, int out_pad_w,
                                            int groups) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, Din, Hin, Win]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, kd, kh, kw]");
  TORCH_CHECK(groups == 1, "This CUTE kernel currently supports groups == 1");
  const int64_t N = x.size(0);
  const int64_t Cin = x.size(1);
  const int64_t Din = x.size(2);
  const int64_t Hin = x.size(3);
  const int64_t Win = x.size(4);
  const int64_t wCin = w.size(0);
  const int64_t Cout = w.size(1);
  const int64_t kd = w.size(2);
  const int64_t kh = w.size(3);
  const int64_t kw = w.size(4);
  TORCH_CHECK(wCin == Cin, "weight.size(0) must equal input channels");
  TORCH_CHECK(stride_d > 0 && stride_h > 0 && stride_w > 0, "strides must be positive");
  TORCH_CHECK(pad_d >= 0 && pad_h >= 0 && pad_w >= 0, "padding must be non-negative");
  TORCH_CHECK(out_pad_d >= 0 && out_pad_h >= 0 && out_pad_w >= 0, "output padding must be non-negative");
  const int64_t Dout = (Din - 1) * stride_d - 2 * pad_d + kd + out_pad_d;
  const int64_t Hout = (Hin - 1) * stride_h - 2 * pad_h + kh + out_pad_h;
  const int64_t Wout = (Win - 1) * stride_w - 2 * pad_w + kw + out_pad_w;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed conv output size");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
