cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kd, int kh, int kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw)
{
  constexpr int Threads  = 128;
  constexpr int P_SUB    = 4;
  constexpr int P_TILE   = Threads * P_SUB;
  constexpr int KCHUNK   = 128;
  constexpr int CO_TILE  = 16;
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int co_base = blockIdx.z * CO_TILE;
  const int p0 = blockIdx.x * P_TILE;
  const int P_total = Dout * Hout * Wout;
  int p[P_SUB];
  bool pvalid[P_SUB];
  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    p[r] = p0 + tid + r * Threads;
    pvalid[r] = (p[r] < P_total);
  }

  const int64_t sXn = (int64_t)Cin * Din * Hin * Win;
  const int64_t sXc = (int64_t)Din * Hin * Win;
  const int64_t sXd = (int64_t)Hin * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  const int64_t sWci = (int64_t)Cout * kd * kh * kw;
  const int64_t sWco = (int64_t)kd * kh * kw;
  const int64_t sWkd = (int64_t)kh * kw;
  const int64_t sWkh = (int64_t)kw;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, Din, Hin, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout, kd, kh, kw),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );

  __shared__ T sW_raw[KCHUNK * CO_TILE];
  __shared__ int sCi[KCHUNK];
  __shared__ int sKz[KCHUNK];
  __shared__ int sKy[KCHUNK];
  __shared__ int sKx[KCHUNK];

  Tensor sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<KCHUNK>{}, Int<CO_TILE>{}),
      make_stride(Int<CO_TILE>{}, Int<1>{})
  );

  int od[P_SUB], oh[P_SUB], ow[P_SUB];
  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    od[r] = 0; oh[r] = 0; ow[r] = 0;
    if (pvalid[r]) {
      od[r] = p[r] / (Hout * Wout);
      int rem = p[r] - od[r] * (Hout * Wout);
      oh[r] = rem / Wout;
      ow[r] = rem - oh[r] * Wout;
    }
  }
  float acc[P_SUB][CO_TILE];
  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    #pragma unroll
    for (int cc = 0; cc < CO_TILE; ++cc) {
      int co = co_base + cc;
      float bv = 0.0f;
      if (B != nullptr && co < Cout) bv = (float)B[co];
      acc[r][cc] = bv;
    }
  }

  const int K_total = Cin * kd * kh * kw;
  const bool unit_stride = (sd == 1 && sh == 1 && sw == 1);

  for (int k0 = 0; k0 < K_total; k0 += KCHUNK) {
    const int kc = min(KCHUNK, K_total - k0);

    for (int idx = tid; idx < KCHUNK; idx += Threads) {
      int kg = k0 + idx;
      bool kv = (kg < K_total);

      int ci = 0, kz = 0, ky = 0, kx = 0;
      if (kv) {
        kx = kg % kw;
        int r0 = kg / kw;
        ky = r0 % kh;
        int r1 = r0 / kh;
        kz = r1 % kd;
        ci = r1 / kd;
      }

      sCi[idx] = ci;
      sKz[idx] = kz;
      sKy[idx] = ky;
      sKx[idx] = kx;

      #pragma unroll
      for (int cc = 0; cc < CO_TILE; ++cc) {
        int co = co_base + cc;
        T wv = T(0);
        if (kv && co < Cout) {
          wv = mW(ci, co, kz, ky, kx);
        }
        sW(idx, cc) = wv;
      }
    }
    __syncthreads();

    #pragma unroll
    for (int r = 0; r < P_SUB; ++r) {
      if (pvalid[r]) {
        for (int idx = 0; idx < kc; ++idx) {
          const int ci = sCi[idx];
          const int kz = sKz[idx];
          const int ky = sKy[idx];
          const int kx = sKx[idx];
          int id, ih, iw;
          bool valid;
          if (unit_stride) {
            id = od[r] + pd - kz;
            ih = oh[r] + ph - ky;
            iw = ow[r] + pw - kx;
            valid = ((unsigned)id < (unsigned)Din) &&
                    ((unsigned)ih < (unsigned)Hin) &&
                    ((unsigned)iw < (unsigned)Win);
          } else {
            int nd = od[r] + pd - kz;
            int nh = oh[r] + ph - ky;
            int nw = ow[r] + pw - kx;
            valid = false;
            id = ih = iw = 0;
            if (nd >= 0 && nh >= 0 && nw >= 0 &&
                (nd % sd) == 0 && (nh % sh) == 0 && (nw % sw) == 0) {
              id = nd / sd;
              ih = nh / sh;
              iw = nw / sw;
              valid = ((unsigned)id < (unsigned)Din) &&
                      ((unsigned)ih < (unsigned)Hin) &&
                      ((unsigned)iw < (unsigned)Win);
            }
          }
          if (valid) {
            const float xv = (float)mX(ci, id, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CO_TILE; ++cc) {
              acc[r][cc] += xv * (float)sW(idx, cc);
            }
          }
        }
      }
    }
    __syncthreads();
  }

  #pragma unroll
  for (int r = 0; r < P_SUB; ++r) {
    if (pvalid[r]) {
      #pragma unroll
      for (int cc = 0; cc < CO_TILE; ++cc) {
        int co = co_base + cc;
        if (co < Cout) {
          mY(co, od[r], oh[r], ow[r]) = (T)acc[r][cc];
        }
      }
    }
  }
}

__device__ __forceinline__ int floor_div_i(int a, int b) {
  return (a >= 0) ? (a / b) : -((-a + b - 1) / b);
}
__device__ __forceinline__ int ceil_div_i(int a, int b) {
  return -floor_div_i(-a, b);
}
__device__ __forceinline__ bool tile_input_range(
    int out_base, int out_tile, int out_size,
    int k, int pad, int stride, int in_size,
    int& in_base, int& in_span) {
  int out_hi = out_base + out_tile - 1;
  if (out_hi > out_size - 1) out_hi = out_size - 1;
  if (out_hi < out_base) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  const int lo_num = out_base + pad - (k - 1);
  const int hi_num = out_hi + pad;
  if (hi_num < 0) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  const int first = ceil_div_i(lo_num, stride);
  const int last = floor_div_i(hi_num, stride);
  if (first > last) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  in_base = (first > 0) ? first : 0;
  int in_hi = (last < in_size - 1) ? last : (in_size - 1);
  in_span = in_hi - in_base + 1;
  if (in_span <= 0) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  return true;
}
template <typename T>
__global__ void conv_transpose3d_smem_tile_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int Din, int Hin, int Win,
    int Cout, int Dout, int Hout, int Wout,
    int kd, int kh, int kw,
    int sd, int sh, int sw,
    int pd, int ph, int pw)
{
