  constexpr int OD_TILE = 2;
  constexpr int OH_TILE = 4;
  constexpr int OW_SUB = 16;
  constexpr int OW_REP = 4;
  constexpr int OW_TILE = OW_REP * OW_SUB;
  constexpr int CI_TILE = 2;
  constexpr int CO_TILE = 16;
  const int tid = threadIdx.x;
  const int n = blockIdx.y;
  const int co_base = blockIdx.z * CO_TILE;
  const int wtiles = (Wout + OW_TILE - 1) / OW_TILE;
  const int htiles = (Hout + OH_TILE - 1) / OH_TILE;
