class ModelNew(nn.Module):
    """
    Transposed 3D convolution implemented with a single custom CUTE/CUDA kernel.
    Parameters are stored in self.conv_transpose3d so the module remains state_dict-compatible
    with the reference nn.ConvTranspose3d module.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: tuple = (1, 1, 1),
                 padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0),
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        self.stride = tuple(int(v) for v in stride)
        self.padding = tuple(int(v) for v in padding)
        self.output_padding = tuple(int(v) for v in output_padding)
        self.groups = int(groups)

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )
        self._ext = conv_transpose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        return self._ext.conv_transpose3d_cute_forward(
            x.contiguous(),
            self.conv_transpose3d.weight.contiguous(),
