            int(self.stride[0]), int(self.stride[1]), int(self.stride[2]),
            int(self.padding[0]), int(self.padding[1]), int(self.padding[2]),
            int(self.output_padding[0]), int(self.output_padding[1]), int(self.output_padding[2]),
            int(self.groups),
