__device__ __forceinline__ int floor_div_i(int a, int b) {
  return (a >= 0) ? (a / b) : -((-a + b - 1) / b);
}
__device__ __forceinline__ int ceil_div_i(int a, int b) {
  return -floor_div_i(-a, b);
}
__device__ __forceinline__ bool tile_input_range(
    int out_base, int out_tile, int out_size,
    int k, int pad, int stride, int in_size,
    int& in_base, int& in_span) {
  int out_hi = out_base + out_tile - 1;
  if (out_hi > out_size - 1) out_hi = out_size - 1;
  if (out_hi < out_base) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  const int lo_num = out_base + pad - (k - 1);
  const int hi_num = out_hi + pad;
  if (hi_num < 0) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  const int first = ceil_div_i(lo_num, stride);
  const int last = floor_div_i(hi_num, stride);
  if (first > last) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  in_base = (first > 0) ? first : 0;
  int in_hi = (last < in_size - 1) ? last : (in_size - 1);
  in_span = in_hi - in_base + 1;
  if (in_span <= 0) {
    in_base = 0;
    in_span = 0;
    return false;
  }
  return true;
}
